import { DatabaseSync } from 'node:sqlite';
import type { Customer, Event, Row } from './model.js';
import { since, until } from './model.js';
import type { Scenario } from './scenarios.js';

/** Independent, real SQL oracle. This is NOT SQL generated by Relate. */
export function openReference(
  customers: Customer[],
  ids: Map<string, string>,
  events: Iterable<Event>,
) {
  const db = new DatabaseSync(':memory:');

  try {
    db.exec(
      'CREATE TABLE customers (id TEXT PRIMARY KEY, key TEXT, name TEXT, portfolio TEXT); CREATE TABLE events (customer TEXT, type TEXT, at TEXT); BEGIN',
    );
    const insertCustomer = db.prepare(
      'INSERT INTO customers VALUES (?, ?, ?, ?)',
    );
    const insertEvent = db.prepare('INSERT INTO events VALUES (?, ?, ?)');

    for (const row of customers)
      insertCustomer.run(ids.get(row.key)!, row.key, row.name, row.portfolio);

    for (const row of events) insertEvent.run(row.customer, row.type, row.at);

    db.exec(
      'COMMIT; CREATE INDEX events_customer_type_at ON events(customer, type, at); ANALYZE',
    );
    const objects = db.prepare(
      "SELECT id, name FROM customers WHERE portfolio = 'north' ORDER BY id LIMIT 25",
    );
    const aggregate = `SELECT c.id, c.name, CAST(COUNT(e.customer) AS TEXT) AS loginCount, MAX(e.at) AS lastLogin FROM candidates c LEFT JOIN events e ON e.customer = c.key AND e.type = 'login' AND e.at >= ? AND e.at < ? GROUP BY c.id, c.name`;
    const enrichment = db.prepare(
      `WITH candidates AS (SELECT * FROM customers WHERE portfolio = 'north' ORDER BY id LIMIT 25) ${aggregate} ORDER BY c.id`,
    );
    const ranking = db.prepare(
      `WITH candidates AS (SELECT * FROM customers WHERE portfolio = 'north') ${aggregate} ORDER BY COUNT(e.customer) DESC, c.id ASC LIMIT 25`,
    );

    return {
      version: db.prepare('SELECT sqlite_version() AS version').get()!.version,
      query(scenario: Scenario): Row[] {
        const result =
          scenario === 'objects'
            ? objects.all()
            : (scenario === 'enrichment' ? enrichment : ranking).all(
                since,
                until,
              );

        return result.map((row) => ({
          id: String(row.id),
          data: {
            name: String(row.name),
            ...(scenario === 'objects'
              ? {}
              : {
                  loginCount: String(row.loginCount),
                  lastLogin:
                    row.lastLogin === null ? null : String(row.lastLogin),
                }),
          },
        }));
      },
      close: () => db.close(),
    };
  } catch (error) {
    db.close();
    throw error;
  }
}
